def normalize(row):
    result={k:CELLS.get(v,v) for k,v in row.items()}
    for k,v in result.items():
        if k not in ('place','transcription_reads','should_read','evidence'): continue
        outside=re.sub(r'\\\(.*?\\\)|\\\[.*?\\\]', '',v,flags=re.S)
        assert not re.search(r'(?<!\\)[_^]',outside),(k,v)
    return result
